#!/usr/bin/env Rscript
# Optional official-prior response calibration; uses completed TGFbeta paired fit.
# Never refits limma, changes FB01 response, or treats known-stimulus compatibility as KL validation.
if(Sys.info()[['sysname']]!='Linux'||Sys.getenv('FIVE_STUDIES_COMPUTE')!='autodl')stop('AutoDL only')
suppressPackageStartupMessages({library(jsonlite);library(digest)})
P<-'/root/five_new_studies_20261020/projects/N02_keloid_genetic_cell_state';OLD<-'/root/autodl-tmp/Five_Studies_Execution_20261020';HERE<-file.path(P,'communication_mechanism_20261021_v1');CAL<-file.path(HERE,'known_stimulus_calibration_v1');SOURCE<-file.path(CAL,'run_TGFbeta_existing_response_calibration_v1.R')
sha<-function(p)digest(file=p,algo='sha256');A<-fromJSON(file.path(CAL,'ROOT_CALIBRATION_APPROVAL.json'),simplifyVector=FALSE);stopifnot(A$status=='APPROVED',A$source_sha256==sha(SOURCE));for(r in A$inputs)stopifnot(file.exists(r$path),unname(file.info(r$path)$size)==r$bytes,sha(r$path)==r$sha256)
F<-fromJSON(file.path(HERE,'FREEZE.json'),simplifyVector=FALSE);stopifnot(A$communication_freeze_sha256==sha(file.path(HERE,'FREEZE.json')))
D<-file.path(P,'mechanisms_20261021/literature_intervention_v1');DEpath<-file.path(D,'results_v1/all7_contrasts_full_HGNC_t_logFC_for_fixed_prior_footprints.tsv.gz');CMPpath<-file.path(D,'results_v1/COMPLETE.json');CM<-fromJSON(CMPpath,simplifyVector=FALSE);rr<-CM$all_outputs[['all7_contrasts_full_HGNC_t_logFC_for_fixed_prior_footprints.tsv.gz']];stopifnot(CM$status=='COMPLETE_FIXED7_PAIRED_PUBLIC_INTERVENTION_RNA_ROOT_REVIEW_PENDING',CM$returncode==0,!is.null(rr),rr$path==DEpath,unname(file.info(DEpath)$size)==rr$bytes,rr$bytes==6543676,rr$sha256=='e3086073af2c85b1da7c34bc1fbcbe0f258a8d009f1cf4c03f0f7f84b7354794',sha(DEpath)==rr$sha256)
OUT<-file.path(CAL,'results_v1');if(dir.exists(OUT))stop('Output exists; no repeated calibration');dir.create(OUT)
options(error=function(){write_json(list(status='FAILED_PRESERVED',message=geterrmessage()),file.path(OUT,'FAILED.json'),pretty=TRUE,auto_unbox=TRUE);quit(save='no',status=1)})
write<-function(x,p)write.table(x,p,sep='\t',quote=FALSE,row.names=FALSE,na='NA')
RDS<-file.path(OLD,'metadata/mechanism_primary_sources/nichenet_priors/ligand_target_matrix_nsga2r_final.rds');for(r in F$inputs)if(r$path==RDS)stopifnot(sha(RDS)==r$sha256);stopifnot(unname(tools::md5sum(RDS))=='b09606b04b2d4490418d9028c0e58b9f')
M<-fromJSON(file.path(OLD,'metadata/nichenetr_optional_source/manifest.json'));for(i in seq_len(nrow(M$files))){z<-M$files[i,];stopifnot(sha(file.path(OLD,'metadata/nichenetr_optional_source',z$path))==z$sha256)}
nn<-source(file.path(OLD,'shared/load_nichenet_activity.R'))$value;LT<-readRDS(RDS);stopifnot(is.matrix(LT),!anyDuplicated(rownames(LT)),!anyDuplicated(colnames(LT)))
x<-read.delim(DEpath,check.names=FALSE,stringsAsFactors=FALSE);cols<-c('dataset','contrast','gene_id','HGNC_symbol','t','logFC','P.Value','adj.P.Val','test_status');stopifnot(all(cols%in%names(x)))
x<-x[x$dataset=='GSE232435'&x$contrast=='TGFbeta_minus_Control',cols,drop=FALSE];stopifnot(nrow(x)==42117L,!anyDuplicated(x$gene_id),!anyDuplicated(x$HGNC_symbol));stopifnot(sum(x$test_status=='TESTED')==15954L)
x$in_official_LT<-x$HGNC_symbol%in%rownames(LT);x$finite_tested<-x$test_status=='TESTED'&is.finite(x$t)&is.finite(x$logFC)&is.finite(x$P.Value)&is.finite(x$adj.P.Val);stopifnot(sum(x$finite_tested)==15954L);write(x,file.path(OUT,'complete_existing_contrast_gene_and_prior_coverage.tsv'))
bg<-x$HGNC_symbol[x$finite_tested&x$in_official_LT];write(data.frame(HGNC_symbol=bg),file.path(OUT,'tested_assay_prior_background.tsv'))
result<-list();members<-list();coverage<-list();priorN<-vapply(seq_len(ncol(LT)),function(j)sum(LT[,j]>0),numeric(1));bgi<-match(bg,rownames(LT));priorBG<-vapply(seq_len(ncol(LT)),function(j)sum(LT[bgi,j]>0),numeric(1))
for(sign in c('Up','Down')){
 direction_ok<-if(sign=='Up')x$t>0&x$logFC>0 else x$t<0&x$logFC<0;q<-x[x$finite_tested&x$in_official_LT&!is.na(direction_ok)&direction_ok,,drop=FALSE];q<-q[order(if(sign=='Up')-q$t else q$t,q$HGNC_symbol),,drop=FALSE];target<-head(q$HGNC_symbol,250L)
 ans<-data.frame(test_ligand=colnames(LT),auroc=NA_real_,aupr=NA_real_,aupr_corrected=NA_real_,pearson=NA_real_,status='RESPONSE_TOO_SMALL_OR_CONSTANT',stringsAsFactors=FALSE)
 if(length(target)>=10L&&length(bg)>=50L&&length(target)<length(bg)){
  score<-nn$predict_ligand_activities(geneset=target,background_expressed_genes=bg,ligand_target_matrix=LT,potential_ligands=colnames(LT));stopifnot(setequal(score$test_ligand,colnames(LT)),!anyDuplicated(score$test_ligand));ix<-match(score$test_ligand,ans$test_ligand);for(n in names(score))ans[ix,n]<-score[[n]];ans$status<-ifelse(is.finite(ans$aupr_corrected),'SCORED','OFFICIAL_NONFINITE_PRESERVED')
 }
 ans$response_sign<-sign;ans$dataset<-'GSE232435';ans$contrast<-'TGFbeta_minus_Control';ans$background_n<-length(bg);ans$target_n<-length(target);ans$prespecified_TGFB_family<-ans$test_ligand%in%c('TGFB1','TGFB2','TGFB3');ans$rank_descriptive<-rank(-ans$aupr_corrected,na.last='keep',ties.method='min');ans$prior_all_targets_n<-priorN;ans$prior_tested_background_targets_n<-priorBG;ans$purpose<-'Known exogenous stimulus compatibility calibration; not keloid external validation or ligand-specific cause'
 result[[sign]]<-ans;members[[sign]]<-data.frame(response_sign=sign,HGNC_symbol=target,position=seq_along(target),source='Existing complete paired3source fit, signed top250 exploratory not FDRset');coverage[[sign]]<-data.frame(response_sign=sign,HGNC_assay_rows=nrow(x),original_tested=sum(x$finite_tested),tested_in_LT=length(bg),response_members=length(target),supplied_ligands=ncol(LT))
}
all<-do.call(rbind,result);write(all,file.path(OUT,'all_LT_ligands_TGFbeta_known_stimulus_Up_Down.tsv'));write(all[all$prespecified_TGFB_family,,drop=FALSE],file.path(OUT,'prespecified_TGFB1_2_3_family_diagnostic.tsv'));write(do.call(rbind,members),file.path(OUT,'fixed_Up_Down_response_members.tsv'));write(do.call(rbind,coverage),file.path(OUT,'complete_calibration_coverage.tsv'));writeLines(capture.output(sessionInfo()),file.path(OUT,'sessionInfo.txt'))
files<-list.files(OUT,full.names=TRUE);rows<-lapply(files,function(p)list(path=p,bytes=unname(file.info(p)$size),sha256=sha(p)));write_json(list(status='COMPLETE_EXISTING_TGFB_RESPONSE_PRIOR_CALIBRATION_NOT_KL_EXTERNAL_VALIDATION',source_sha256=sha(SOURCE),communication_freeze_sha256=sha(file.path(HERE,'FREEZE.json')),existing_DE_sha256=sha(DEpath),existing_producer_sha256=sha(CMPpath),approval_sha256=sha(file.path(CAL,'ROOT_CALIBRATION_APPROVAL.json')),all_outputs=rows,source_material='Primary foreskin fibroblasts3sources N5/N6/N8; original9samples3conditions pairedfit; not keloid',no_new_limma_or_program_fit=TRUE,all_ligands_negative_and_NA_preserved=TRUE,interpretation='TGFB1 need not rankfirst; related family/shared-response priors may overlap. Down compatibility not inhibitory ligand evidence. This checks modelresponsecontext not clinical prediction.'),file.path(OUT,'COMPLETE.json.tmp'),pretty=TRUE,auto_unbox=TRUE,na='null');stopifnot(file.rename(file.path(OUT,'COMPLETE.json.tmp'),file.path(OUT,'COMPLETE.json')))
